namespace gui_forms {

// NotifyIcon's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/notify_icon.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The icon at one or more sizes, premultiplied BGRA8 (HostImage). Throws std::invalid_argument for more than 8 images or an image that is malformed or larger than 256 pixels a side. A write updates a shown icon, even when unchanged. UI thread only (std::logic_error).
template <typename Declaring>
struct NotifyIconIconCapability {
    PropertyView<std::vector<HostImage>, NotifyIconIconCapability<Declaring>> icon;

    static void assign(NotifyIconIconCapability& capability, std::vector<HostImage> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.icon), std::move(incoming));
    }

    static std::vector<HostImage> read(const NotifyIconIconCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::vector<HostImage> current = control.read_view(capability.icon);
        return current;
    }
};

// Whether the application wants the icon shown. Every write shows or removes the icon, even when unchanged, and status() then holds the host's answer: unsupported without a host or without the notification_area capability, invalid_argument while there is no icon image. A visible icon without an image is shown once an image is set. UI thread only (std::logic_error).
template <typename Declaring>
struct NotifyIconVisibleCapability {
    PropertyView<bool, NotifyIconVisibleCapability<Declaring>> visible;

    static void assign(NotifyIconVisibleCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.visible), std::move(incoming));
    }

    static bool read(const NotifyIconVisibleCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        bool current = control.read_view(capability.visible);
        return current;
    }
};

// The menu shown on the icon's context gesture. Hosts with native tray menus (notification_area_menus) show its rows natively; choosing a row executes its command and raises menu_item_invoked. Submenus are left out. Without native tray menus only click is raised. UI thread only (std::logic_error).
template <typename Declaring>
struct NotifyIconContextMenuCapability {
    PropertyCell<std::shared_ptr<ContextMenu>, NotifyIconContextMenuCapability<Declaring>> context_menu{};

    static void assign(NotifyIconContextMenuCapability& capability, std::shared_ptr<ContextMenu> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.context_menu), incoming);
        if (!capability.context_menu.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.context_menu));
    }
};

// Every NotifyIcon capability, in the order the declaring class takes them.
template <typename Declaring>
struct NotifyIconCapabilities : public NotifyIconIconCapability<Declaring>,
                                public TextCapability<Declaring>,
                                public NotifyIconVisibleCapability<Declaring>,
                                public NotifyIconContextMenuCapability<Declaring> {};

} // namespace gui_forms
